@file:Suppress("UNUSED_VARIABLE", "UNUSED_PARAMETER", "VARIABLE_WITH_REDUNDANT_INITIALIZER", "UNREACHABLE_CODE", "NAME_SHADOWING")
package hunter.app.installcatalog

import hunter.browser.*

@JsName("Boolean") private external var global_Boolean: dynamic
@JsName("Math") private external var global_Math: dynamic
@JsName("Set") private external var global_Set: dynamic
@JsName("window") private external var global_window: dynamic
@JsName("globalThis") private external var global_globalThis: dynamic

internal fun installCatalog() {
    dynamicValue((fun(root: dynamic): dynamic {
        val E: dynamic = root.Engine
        val rename: dynamic = jsonValue("{\"chair\":\"Sentadilla a silla\",\"goblet\":\"Sentadilla con mancuerna al pecho\",\"press\":\"Press de pecho en suelo\",\"neutral\":\"Press de pecho con agarre neutro\",\"rdl\":\"Peso muerto rumano con mancuernas\",\"row\":\"Remo unilateral con mancuerna\",\"bentrow\":\"Remo inclinado con mancuernas\",\"curl\":\"Flexión de bíceps con mancuernas\",\"hammer\":\"Flexión de bíceps con agarre martillo\",\"deadbug\":\"Extensión alterna de brazo y pierna\",\"bird\":\"Extensión contralateral en cuadrupedia\",\"plank\":\"Plancha abdominal\",\"reverse\":\"Apertura de brazos boca abajo\"}")
        E.exercises.forEach((fun(e: dynamic): dynamic {
            e.name = jsOr(rename[e.id]) { e.name }
            e.category = (if (truth((e.group === "Movilidad"))) "Movilidad" else "Fuerza")
            e.requirements = (if (truth((e.equipment === "db"))) jsonValue("[\"db\"]") else js("[]"))
            e.impact = "Bajo"
            return absent
        }))
        val rows: dynamic = jsonValue("[[\"benchpress\",\"Press de banca con mancuernas\",\"Pecho\",\"db,bench\",1,\"reps\",false,\"Túmbate sobre un banco de entrenamiento estable, con pies apoyados y mancuernas junto al pecho.|Empuja las cargas hacia arriba sin chocar las mancuernas.|Baja con control hasta un recorrido cómodo para tus hombros.\",\"No uses una mesa, cama o silla como banco. Mantén las muñecas alineadas.\",\"press\"],[\"inclinebench\",\"Press inclinado con mancuernas\",\"Pecho\",\"db,bench\",1,\"reps\",false,\"Ajusta un banco de entrenamiento a una inclinación moderada.|Apoya espalda y pies; lleva las mancuernas a los lados del pecho.|Empuja hacia arriba y baja sin rebotes.\",\"El banco debe bloquearse en la posición elegida. No arquees la zona lumbar.\",\"neutral\"],[\"kneepush\",\"Flexión de brazos con rodillas apoyadas\",\"Pecho\",\"\",0,\"reps\",false,\"Apoya manos y rodillas sobre el suelo, con una línea recta desde rodillas a cabeza.|Flexiona los codos y acerca el pecho al suelo.|Empuja para regresar manteniendo el abdomen activo.\",\"No dejes las caderas atrás ni hundas la espalda.\",\"wall\"],[\"closepush\",\"Flexión con manos próximas\",\"Pecho\",\"\",2,\"reps\",false,\"En posición de flexión, acerca ligeramente las manos sin forzar las muñecas.|Baja el pecho con los codos próximos al cuerpo.|Empuja hasta recuperar la posición inicial.\",\"No es necesario juntar las manos en diamante.\",\"kneepush\"],[\"squeezepress\",\"Press de pecho con mancuernas juntas\",\"Pecho\",\"db\",1,\"reps\",false,\"Túmbate en el suelo y sujeta las mancuernas juntas sobre el pecho.|Empuja ambas cargas hacia arriba con las palmas enfrentadas.|Baja despacio hasta apoyar suavemente los brazos.\",\"Usa cargas que no resbalen y evita apretar con fuerza excesiva.\",\"neutral\"],[\"sumo\",\"Sentadilla con postura amplia\",\"Piernas\",\"\",1,\"reps\",false,\"Separa los pies algo más que los hombros y orienta las puntas ligeramente hacia fuera.|Flexiona caderas y rodillas manteniendo los pies apoyados.|Sube con control.\",\"Las rodillas siguen la dirección de los pies; no fuerces la apertura.\",\"squat\"],[\"dbsumo\",\"Sentadilla amplia con mancuerna\",\"Piernas\",\"db\",1,\"reps\",false,\"Sostén una mancuerna delante del cuerpo con los brazos extendidos.|Adopta una postura amplia y baja flexionando caderas y rodillas.|Empuja el suelo para volver a subir.\",\"Mantén la mancuerna cerca y la espalda en una posición cómoda.\",\"sumo\"],[\"reverselunge\",\"Zancada hacia atrás\",\"Piernas\",\"\",1,\"reps\",true,\"De pie junto a un apoyo si lo necesitas, da un paso atrás.|Flexiona ambas rodillas hasta un recorrido cómodo.|Empuja con el pie delantero para volver y completa el otro lado.\",\"Evita pasos demasiado estrechos o perder el equilibrio.\",\"chair\"],[\"dblunge\",\"Zancada hacia atrás con mancuernas\",\"Piernas\",\"db\",2,\"reps\",true,\"Sostén las mancuernas a los lados y da un paso atrás.|Baja con control flexionando ambas rodillas.|Vuelve a la posición inicial y repite en ambos lados.\",\"Domina primero la variante sin cargas.\",\"reverselunge\"],[\"split\",\"Sentadilla dividida\",\"Piernas\",\"\",1,\"reps\",true,\"Coloca un pie delante y otro detrás sin cruzarlos.|Baja verticalmente flexionando ambas rodillas.|Sube manteniendo los pies en el mismo lugar.\",\"Un apoyo estable puede ayudar al equilibrio.\",\"chair\"],[\"lateralunge\",\"Zancada lateral\",\"Piernas\",\"\",1,\"reps\",true,\"Da un paso amplio hacia un lado.|Flexiona la rodilla de ese lado y lleva la cadera atrás.|Empuja con ese pie para volver al centro.\",\"No fuerces profundidad ni estires bruscamente la otra pierna.\",\"squat\"],[\"stepup\",\"Subida a plataforma baja\",\"Piernas\",\"step\",1,\"reps\",true,\"Coloca un pie sobre una plataforma baja de ejercicio fija.|Sube empujando con esa pierna y apoya el otro pie.|Desciende despacio y alterna la pierna de inicio.\",\"No uses sillas, pilas de libros o superficies que se muevan.\",\"march\"],[\"wallsit\",\"Sentadilla isométrica en pared\",\"Piernas\",\"\",1,\"sec\",false,\"Apoya la espalda en una pared y adelanta un poco los pies.|Deslízate hacia abajo hasta un ángulo cómodo.|Mantén la postura respirando y vuelve a subir con control.\",\"No es necesario bajar hasta 90 grados.\",\"chair\"],[\"singlecalf\",\"Elevación de talón a una pierna\",\"Piernas\",\"\",1,\"reps\",true,\"Colócate junto a una pared y levanta ligeramente un pie.|Sube el talón de la pierna apoyada.|Baja despacio y cambia de pierna.\",\"Usa apoyo y no rebotes.\",\"calf\"],[\"seatedcalf\",\"Elevación de talones sentado\",\"Piernas\",\"\",0,\"reps\",false,\"Siéntate en una silla estable con los pies bajo las rodillas.|Eleva ambos talones manteniendo las puntas apoyadas.|Baja lentamente.\",\"Mantén los tobillos alineados con las piernas.\",\"calf\"],[\"singlebridge\",\"Puente de glúteo a una pierna\",\"Cadera\",\"\",2,\"reps\",true,\"Túmbate boca arriba, apoya un pie y eleva la otra pierna.|Sube la pelvis con la pierna apoyada.|Baja lentamente sin girar la cadera.\",\"Si pierdes control, apoya ambos pies.\",\"bridge\"],[\"dbbridge\",\"Puente de glúteos con mancuerna\",\"Cadera\",\"db\",1,\"reps\",false,\"Boca arriba, coloca una mancuerna ligera y acolchada sobre la pelvis y sujétala.|Apoya los pies y eleva la pelvis.|Baja despacio manteniendo la carga estable.\",\"Evita colocar la carga sobre el abdomen.\",\"bridge\"],[\"kickback\",\"Extensión de cadera en cuadrupedia\",\"Cadera\",\"\",0,\"reps\",true,\"Apoya manos y rodillas en el suelo.|Lleva una pierna hacia atrás sin arquear la espalda.|Regresa despacio y repite con la otra pierna.\",\"El movimiento termina antes de que la pelvis gire.\",\"bridge\"],[\"clam\",\"Apertura de cadera de lado\",\"Cadera\",\"\",0,\"reps\",true,\"Túmbate de lado con las rodillas flexionadas y pies juntos.|Abre la rodilla superior sin separar los pies.|Baja con control y cambia de lado.\",\"Evita rodar el torso hacia atrás.\",\"sideleg\"],[\"singlehinge\",\"Bisagra de cadera con apoyo\",\"Cadera\",\"\",1,\"reps\",true,\"Apóyate en una pared con una mano y carga el peso en una pierna.|Lleva la cadera atrás inclinando suavemente el torso.|Vuelve a erguirte y cambia de lado.\",\"El apoyo es para equilibrio; no busques tocar el suelo.\",\"hinge\"],[\"sumodead\",\"Peso muerto con postura amplia\",\"Cadera\",\"db\",1,\"reps\",false,\"Sostén una mancuerna entre las piernas, con pies algo separados.|Lleva cadera atrás y flexiona ligeramente las rodillas.|Vuelve a erguirte sin inclinarte hacia atrás al terminar.\",\"Mantén la carga próxima y el cuello alineado.\",\"hinge\"],[\"pullover\",\"Extensión de hombros con mancuerna en suelo\",\"Espalda\",\"db\",2,\"reps\",false,\"Boca arriba, sujeta una mancuerna ligera sobre el pecho con ambas manos.|Llévala lentamente hacia atrás solo hasta un rango cómodo.|Regresa sobre el pecho sin arquear la espalda.\",\"Evita bajar la carga si molesta el hombro.\",\"prone\"],[\"reversefly\",\"Apertura posterior con mancuernas\",\"Espalda\",\"db\",1,\"reps\",false,\"Inclina el torso desde la cadera con rodillas suaves.|Con cargas ligeras, abre los brazos a los lados.|Baja despacio manteniendo el torso estable.\",\"No uses impulso ni eleves los hombros hacia las orejas.\",\"prone\"],[\"towelrow\",\"Remo isométrico con toalla\",\"Espalda\",\"\",0,\"sec\",false,\"Sentado, pasa una toalla resistente alrededor de las plantas de los pies.|Sujeta ambos extremos y tira suavemente hacia el torso sin mover los pies.|Mantén unos segundos respirando y afloja.\",\"No enrolles la toalla en el cuello ni la ancles a una puerta.\",\"prone\"],[\"scapular\",\"Retracción de omóplatos de pie\",\"Espalda\",\"\",0,\"reps\",false,\"De pie o sentado, coloca los brazos junto al cuerpo.|Acerca suavemente los omóplatos sin elevar los hombros.|Relaja y repite con control.\",\"No arquees la espalda para aumentar el recorrido.\",\"prone\"],[\"overheadpress\",\"Press de hombros con mancuernas\",\"Hombros\",\"db\",1,\"reps\",false,\"Sostén mancuernas ligeras a la altura de los hombros.|Empuja hacia arriba hasta una posición cómoda.|Baja lentamente a la posición inicial.\",\"Mantén las costillas controladas; no compenses arqueando la espalda.\",\"wallslide\"],[\"frontlift\",\"Elevación frontal con mancuernas\",\"Hombros\",\"db\",1,\"reps\",false,\"Sujeta cargas ligeras delante de los muslos.|Eleva los brazos hasta una altura cómoda, como máximo al nivel de los hombros.|Baja despacio.\",\"No balancees el cuerpo ni bloquees los codos.\",\"wallslide\"],[\"shouldertap\",\"Toque alterno de hombros\",\"Core\",\"\",2,\"reps\",false,\"En posición de flexión, separa ligeramente los pies.|Toca un hombro con la mano contraria y vuelve a apoyarla.|Alterna lados con el torso estable.\",\"Cada toque cuenta una repetición.\",\"bird\"],[\"seatedcurl\",\"Flexión de bíceps sentado\",\"Brazos\",\"db\",0,\"reps\",false,\"Siéntate en una silla firme con espalda cómoda y pies apoyados.|Flexiona los codos para elevar las mancuernas.|Baja lentamente sin mover los brazos hacia delante.\",\"No balancees el torso.\",\"curl\"],[\"concentration\",\"Flexión de bíceps con apoyo\",\"Brazos\",\"db\",1,\"reps\",true,\"Sentado, apoya suavemente el brazo en la cara interna del muslo.|Flexiona el codo para elevar una mancuerna.|Baja despacio y cambia de brazo.\",\"No empujes la carga con el cuerpo.\",\"curl\"],[\"tricep\",\"Extensión de tríceps inclinada\",\"Brazos\",\"db\",1,\"reps\",true,\"Inclina el torso y apoya una mano en una superficie fija.|Con el otro brazo junto al cuerpo, extiende el codo hacia atrás.|Flexiona de nuevo sin mover el hombro.\",\"Usa una carga ligera y no bloquees con fuerza el codo.\",\"hammer\"],[\"lyingtricep\",\"Extensión de tríceps en suelo\",\"Brazos\",\"db\",1,\"reps\",false,\"Túmbate en el suelo con cargas ligeras sobre el pecho.|Flexiona los codos llevando las mancuernas a los lados de la cabeza.|Extiende los codos con control.\",\"Evita llevar las cargas sobre la cara.\",\"neutral\"],[\"reversecurl\",\"Flexión de bíceps con agarre prono\",\"Brazos\",\"db\",1,\"reps\",false,\"Sujeta mancuernas ligeras con las palmas hacia atrás.|Flexiona los codos manteniendo las muñecas alineadas.|Baja lentamente.\",\"Reduce la carga si doblas las muñecas.\",\"hammer\"],[\"sideplank\",\"Plancha lateral con rodillas\",\"Core\",\"\",1,\"sec\",true,\"De lado, apoya un antebrazo bajo el hombro y las rodillas flexionadas.|Eleva la cadera formando una línea entre rodillas y cabeza.|Mantén respirando, baja y cambia de lado.\",\"Registra los segundos de un lado tras completar ambos.\",\"heel\"],[\"kneelingplank\",\"Plancha abdominal con rodillas\",\"Core\",\"\",0,\"sec\",false,\"Apoya antebrazos y rodillas en el suelo.|Alinea tronco y muslos con el abdomen activo.|Mantén mientras puedes respirar y sostener la postura.\",\"No hundas la zona lumbar.\",\"heel\"],[\"reversecrunch\",\"Elevación de pelvis corta\",\"Core\",\"\",1,\"reps\",false,\"Boca arriba, eleva las rodillas con las piernas flexionadas.|Acerca suavemente las rodillas al torso elevando un poco la pelvis.|Regresa sin balancear las piernas.\",\"El recorrido es corto; evita impulso.\",\"heel\"],[\"curlup\",\"Flexión abdominal corta\",\"Core\",\"\",1,\"reps\",false,\"Boca arriba con rodillas flexionadas, manos sobre los muslos.|Eleva ligeramente cabeza y hombros deslizando las manos.|Baja despacio.\",\"No tires del cuello ni te impulses.\",\"heel\"],[\"standingcore\",\"Elevación alterna de rodilla\",\"Core\",\"\",0,\"reps\",false,\"De pie junto a un apoyo estable, activa suavemente el abdomen.|Eleva una rodilla hasta una altura cómoda.|Baja y alterna.\",\"Cada elevación cuenta una repetición.\",\"heel\"],[\"suitcase\",\"Sujeción unilateral de mancuerna\",\"Core\",\"db\",1,\"sec\",true,\"De pie, sujeta una mancuerna a un lado del cuerpo.|Mantén el torso erguido sin inclinarte hacia la carga.|Respira y cambia de mano tras el intervalo.\",\"Registra segundos por lado después de hacer ambos.\",\"standingcore\"],[\"fastmarch\",\"Marcha rápida sin saltos\",\"Cardio\",\"\",0,\"sec\",false,\"Marcha en el lugar alternando pies y brazos.|Aumenta ligeramente el ritmo sin saltar.|Mantén un paso estable y reduce la velocidad al terminar.\",\"Deja libre el suelo y usa un ritmo que te permita hablar.\",\"march\"],[\"sidestep\",\"Paso lateral continuo\",\"Cardio\",\"\",0,\"sec\",false,\"Da un paso hacia un lado y acerca el otro pie.|Repite al lado contrario con rodillas suaves.|Acompaña con los brazos sin cruzar los pies.\",\"No deslices los pies sobre una superficie resbaladiza.\",\"march\"],[\"stepjack\",\"Aperturas laterales sin salto\",\"Cardio\",\"\",0,\"sec\",false,\"Abre un pie hacia un lado mientras elevas los brazos hasta una altura cómoda.|Vuelve al centro.|Alterna lados manteniendo siempre un pie apoyado.\",\"No fuerces el recorrido de hombros.\",\"sidestep\"],[\"box\",\"Boxeo al aire suave\",\"Cardio\",\"\",0,\"sec\",false,\"De pie, pies separados y rodillas suaves.|Extiende alternativamente los brazos al frente sin golpear objetos.|Recoge los brazos y mantén un ritmo cómodo.\",\"No bloquees los codos ni uses mancuernas para golpear.\",\"march\"],[\"heelback\",\"Talones alternos hacia atrás\",\"Cardio\",\"\",0,\"sec\",false,\"De pie junto a un apoyo si lo necesitas.|Lleva un talón hacia atrás flexionando la rodilla.|Alterna piernas sin saltos.\",\"No arquees la espalda para subir el talón.\",\"march\"],[\"kneeliftcardio\",\"Rodillas alternas sin salto\",\"Cardio\",\"\",0,\"sec\",false,\"De pie, eleva una rodilla y acompaña con el brazo contrario.|Vuelve a apoyar el pie.|Alterna a un ritmo regular sin saltar.\",\"Escoge una altura que permita mantener el equilibrio.\",\"fastmarch\"],[\"walk\",\"Caminata continua en casa\",\"Cardio\",\"\",0,\"sec\",false,\"Despeja un recorrido corto o camina en el sitio.|Avanza a un ritmo cómodo y gira con pasos pequeños.|Mantén la respiración regular.\",\"Evita girar sobre una rodilla fija.\",\"march\"],[\"skater\",\"Paso de patinador sin salto\",\"Cardio\",\"\",1,\"sec\",false,\"Desplaza el peso de un pie al otro con pasos laterales.|Lleva suavemente la otra pierna hacia atrás sin cruzarla en exceso.|Alterna con el torso controlado.\",\"Mantén el pie de apoyo estable.\",\"sidestep\"],[\"jog\",\"Trote suave en el lugar\",\"Cardio\",\"\",1,\"sec\",false,\"Trota con pasos cortos sobre una superficie despejada.|Aterriza suavemente con las rodillas flexibles.|Reduce a marcha si pierdes control o te falta el aire.\",\"Evita golpes fuertes contra el suelo.\",\"fastmarch\"],[\"jumpjack\",\"Saltos con apertura de piernas\",\"Cardio\",\"\",2,\"sec\",false,\"Desde pies juntos, salta abriendo las piernas y elevando los brazos.|Aterriza con rodillas suaves.|Vuelve con otro salto pequeño.\",\"Necesitas espacio, suelo estable y tolerancia a los saltos.\",\"stepjack\"],[\"rope\",\"Salto de cuerda simulado\",\"Cardio\",\"\",2,\"sec\",false,\"Simula el giro de una cuerda con las muñecas.|Da saltos pequeños con ambos pies.|Aterriza con suavidad y mantén una cadencia controlada.\",\"Evita saltos altos y detente si molestan tobillos o rodillas.\",\"fastmarch\"],[\"mountain\",\"Escalador lento\",\"Cardio\",\"\",2,\"sec\",false,\"Colócate en posición de flexión con manos bajo hombros.|Acerca una rodilla al torso sin mover mucho la pelvis.|Vuelve y alterna lentamente.\",\"No rebotes ni hundas la espalda.\",\"kneeliftcardio\"],[\"squatstep\",\"Sentadilla y paso lateral\",\"Cardio\",\"\",1,\"sec\",false,\"Realiza una sentadilla de recorrido cómodo.|Al subir, da un paso lateral.|Repite cambiando de lado.\",\"Prioriza el control antes que la velocidad.\",\"sidestep\"],[\"shadowcombo\",\"Boxeo al aire con pasos\",\"Cardio\",\"\",1,\"sec\",false,\"Adopta una postura cómoda y da pasos cortos.|Alterna golpes suaves al aire con los brazos.|Desplázate sin cruzar los pies y respira continuamente.\",\"Sin cargas en las manos y sin bloquear los codos.\",\"box\"],[\"hipcircle\",\"Círculos suaves de cadera\",\"Movilidad\",\"\",0,\"sec\",false,\"De pie junto a un apoyo estable, separa los pies.|Dibuja círculos pequeños con la pelvis.|Cambia de dirección lentamente.\",\"No busques el máximo recorrido.\",\"march\"],[\"chestopen\",\"Apertura suave de pecho\",\"Movilidad\",\"\",0,\"sec\",false,\"De pie, coloca las manos cerca de las caderas.|Lleva suavemente los hombros hacia atrás.|Mantén una respiración tranquila sin arquear la espalda.\",\"No fuerces los brazos detrás del cuerpo.\",\"shoulder\"],[\"thoracic\",\"Rotación torácica de lado\",\"Movilidad\",\"\",0,\"reps\",true,\"Túmbate de lado con rodillas flexionadas y brazos al frente.|Abre el brazo superior girando suavemente el pecho.|Vuelve despacio y cambia de lado.\",\"Mantén juntas las rodillas; no fuerces el hombro al suelo.\",\"shoulder\"],[\"hipflex\",\"Estiramiento de flexores de cadera\",\"Movilidad\",\"\",0,\"sec\",true,\"Coloca una rodilla sobre una superficie acolchada y el otro pie delante.|Lleva suavemente la pelvis hacia delante sin arquear la espalda.|Mantén una tensión ligera y cambia de lado.\",\"Evita dolor o presión fuerte sobre la rodilla apoyada.\",\"hipcircle\"],[\"hamstretch\",\"Estiramiento posterior de muslo\",\"Movilidad\",\"\",0,\"sec\",true,\"Sentado en una silla firme, extiende una pierna con el talón apoyado.|Inclina suavemente el torso desde la cadera.|Mantén una tensión ligera y cambia de pierna.\",\"No redondees la espalda buscando llegar al pie.\",\"ankle\"],[\"calfstretch\",\"Estiramiento de pantorrilla en pared\",\"Movilidad\",\"\",0,\"sec\",true,\"Apoya las manos en una pared y lleva un pie atrás.|Mantén el talón trasero apoyado mientras flexionas la rodilla delantera.|Sostén suavemente y cambia de pierna.\",\"El pie trasero apunta al frente.\",\"ankle\"],[\"wrist\",\"Movilidad de muñecas\",\"Movilidad\",\"\",0,\"sec\",false,\"Sentado o de pie, mantén los antebrazos cómodos.|Dibuja círculos pequeños con las muñecas.|Alterna con flexión y extensión suaves.\",\"Sin carga sobre las manos durante este ejercicio.\",\"shoulder\"],[\"neck\",\"Movilidad suave de cuello\",\"Movilidad\",\"\",0,\"sec\",false,\"Siéntate erguido con los hombros relajados.|Gira la cabeza lentamente hacia un lado y vuelve al centro.|Repite al otro lado sin hacer círculos completos.\",\"Interrumpe si aparece mareo o dolor.\",\"shoulder\"],[\"breathing\",\"Respiración tranquila de recuperación\",\"Movilidad\",\"\",0,\"sec\",false,\"Siéntate o túmbate en una posición cómoda.|Inhala de forma tranquila sin forzar la profundidad.|Exhala suavemente y continúa con un ritmo natural.\",\"No retengas el aire ni fuerces respiraciones profundas.\",\"march\"]]")
        if (true) {
            val iterator11: dynamic = iteratorOf(rows)
            while (true) {
                val next12: dynamic = iterator11.next()
                if (truth(next12.done)) break
                var r: dynamic = absent
                r = next12.value
                var id: dynamic = absent
                var name: dynamic = absent
                var group: dynamic = absent
                var eq: dynamic = absent
                var level: dynamic = absent
                var unit: dynamic = absent
                var sides: dynamic = absent
                var steps: dynamic = absent
                var cue: dynamic = absent
                var alternative: dynamic = absent
                val unpacked13: dynamic = fromIterable(r)
                id = unpacked13[0]
                name = unpacked13[1]
                group = unpacked13[2]
                eq = unpacked13[3]
                level = unpacked13[4]
                unit = unpacked13[5]
                sides = unpacked13[6]
                steps = unpacked13[7]
                cue = unpacked13[8]
                alternative = unpacked13[9]
                E.exercises.push(jsObject { obj14 ->
                    obj14["id"] = id
                    obj14["name"] = name
                    obj14["group"] = group
                    obj14["equipment"] = (if (truth(eq.includes("db"))) "db" else "body")
                    obj14["level"] = level
                    obj14["unit"] = unit
                    obj14["sides"] = sides
                    obj14["steps"] = steps.replaceAll("|", " ")
                    obj14["instructions"] = steps.split("|")
                    obj14["cue"] = cue
                    obj14["alternative"] = alternative
                    obj14["category"] = (if (truth((group === "Cardio"))) "Cardio" else (if (truth((group === "Movilidad"))) "Movilidad" else "Fuerza"))
                    obj14["requirements"] = (if (truth(eq)) eq.split(",") else js("[]"))
                    obj14["impact"] = (if (truth(dynamicValue(jsonValue("[\"jog\",\"jumpjack\",\"rope\"]")).includes(id))) "Con saltos" else "Bajo")
                })
            }
        }
        val tips: dynamic = jsonValue("{\"Piernas\":[\"Apoya todo el pie y deja que las rodillas sigan la dirección de las puntas.\",\"Baja sin dejarte caer. Usa una profundidad que puedas controlar.\"],\"Pecho\":[\"Prepara una base estable antes de empezar.\",\"Mantén las muñecas alineadas y controla la bajada.\"],\"Cadera\":[\"Inicia desde la cadera, no desde la zona lumbar.\",\"Mantén la pelvis estable y evita los rebotes.\"],\"Espalda\":[\"Relaja el cuello y mantén el torso estable.\",\"Mueve la carga sin balancearte ni encoger los hombros.\"],\"Brazos\":[\"Coloca los codos en una posición estable.\",\"Evita impulsar la carga con el torso.\"],\"Hombros\":[\"Usa cargas ligeras y un recorrido cómodo.\",\"Evita compensar arqueando la espalda.\"],\"Core\":[\"Activa suavemente el abdomen sin bloquear la respiración.\",\"Termina la serie cuando dejes de controlar la postura.\"],\"Cardio\":[\"Despeja el suelo y comienza a un ritmo suave.\",\"Baja el ritmo si no puedes hablar con comodidad.\"],\"Movilidad\":[\"Busca una tensión suave, no dolor.\",\"Muévete despacio sin rebotes ni posiciones forzadas.\"]}")
        E.exercises.forEach((fun(e: dynamic): dynamic {
            e.instructions = jsOr(e.instructions) { e.steps.split(jsRegExp("\\.\\s+", "")).filter(global_Boolean) }
            e.setup = tips[e.group][0]
            e.control = tips[e.group][1]
